package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
import static it.cavallium.rockserver.distributed.ratis.RatisSnapshotCohortRpc.*;

/** Borrowed async routed clients; every request remains bound to its original voter/process/pool. */
public final class RatisSnapshotCohortClient implements RatisDatabaseBackupDriver.CohortTransport {
    private record Pool(UUID node,UUID incarnation,UUID process,UUID pool){}
    private final Map<UUID,RatisRoutedClient> routed;private final java.util.function.Function<UUID,RatisRoutedClient.PreparedSnapshotCapture> frozenCapture;private final Map<UUID,RatisRoutedClient.SnapshotTarget> targets=new ConcurrentHashMap<>();
    public RatisSnapshotCohortClient(Map<UUID,RatisRoutedClient> routed,java.util.function.Function<UUID,RatisRoutedClient.PreparedSnapshotCapture> frozenCapture){this.routed=Map.copyOf(routed);this.frozenCapture=Objects.requireNonNull(frozenCapture);}
    private RatisRoutedClient client(UUID group)throws IOException{var client=routed.get(group);if(client==null)throw new IOException("Cohort group has no declared routed client");return client;}
    private static Capabilities supported(RatisRoutedClient.SnapshotTarget target,long ttl)throws IOException{var cap=target.cohort();if(cap==null)throw new IOException("Original owner does not support native cohort capture");var peer=target.replica();if(!cap.nodeId().equals(peer.nodeId())||!cap.nodeIncarnation().equals(peer.nodeIncarnation())||ttl>cap.maximumReadonlyMillis()||ttl>cap.poolMaximumAgeMillis()||cap.currentCohorts()>=cap.maximumCohorts()||cap.registryEntries()>=cap.registryMaximumEntries()||cap.registryBytes()>=cap.registryMaximumBytes()||cap.poolPins()>=cap.poolMaximumPins()||cap.poolBytes()>=cap.poolMaximumBytes()||cap.poolNextEstimatedBytes()>cap.poolMaximumBytes()-cap.poolBytes()||cap.poolFreeBytes()<cap.poolMinimumFreeBytes())throw new IOException("Declared cohort exceeds actual owner/pool capabilities");return cap;}
    @Override public CompletableFuture<Void> requireSupported(DatabaseBackupDefinition definition,RatisDatabaseBackupDriver.Policy policy)throws IOException{
        var pools=new HashMap<Pool,Integer>();var bytes=new HashMap<Pool,Long>();var definitions=new HashMap<Pool,Set<UUID>>();CompletableFuture<Void> work=CompletableFuture.completedFuture(null);
        for(var domain:definition.domains())for(var fence:domain.fences())for(var member:fence.participants()){var client=client(member.groupId());work=work.thenCompose(ignored->client.snapshotTargetAsync(fence,member.groupId()).thenApply(target->{try{var cap=supported(target,policy.retention().toMillis());long charge=RatisSnapshotPins.TOMBSTONE_BYTES+(long)fence.encode().length+RangeMutationHistory.accountedScopeBytes(member.scope());if(charge>cap.registryMaximumBytes()-cap.registryBytes())throw new IOException("Declared cohort registry metadata exceeds admission");var pool=new Pool(cap.nodeId(),cap.nodeIncarnation(),cap.processIncarnation(),cap.poolId());pools.merge(pool,1,Integer::sum);bytes.merge(pool,124L,Long::sum);if(definitions.computeIfAbsent(pool,k->new HashSet<>()).add(fence.fenceId()))bytes.merge(pool,4L+fence.encode().length,Long::sum);return null;}catch(IOException failed){throw new CompletionException(failed);}}));}
        return work.thenApply(ignored->{if(pools.size()>policy.maximumCohorts()||pools.values().stream().anyMatch(count->count>MAX_MEMBERS)||bytes.values().stream().anyMatch(size->size+72>MAX_REQUEST_BYTES-ScopedTransactionRpc.HEADER_BYTES))throw new CompletionException(new IOException("Declared cohort count/member/frame budget exhausted"));return null;});
    }
    @Override public CompletableFuture<List<RatisDatabaseBackupJournal.CohortRequest>> qualify(DatabaseBackupDefinition definition,Map<UUID,RatisRoutedClient.PreparedSnapshotCapture> frozen,RatisDatabaseBackupDriver.Policy policy)throws IOException{
        var pools=new LinkedHashMap<Pool,List<RatisDatabaseBackupJournal.Member>>();CompletableFuture<Void> work=CompletableFuture.completedFuture(null);
        for(var entry:frozen.entrySet().stream().sorted(Map.Entry.comparingByKey(RangeDirectoryCodec.UUID_ORDER)).toList()){var group=entry.getKey();var prepared=entry.getValue();var client=client(group);work=work.thenCompose(ignored->client.cohortQuery(prepared.target(),OWNER,prepared.request().encode()).thenApply(bytes->{try{var owner=RatisSnapshotOwner.decode(bytes);if(!owner.groupId().equals(group)||owner.rangeEpoch()!=prepared.target().descriptor().rangeEpoch()||!Arrays.equals(owner.schemaDigest(),prepared.request().fence().participant(group).schemaDigest())||!owner.incarnation().equals(prepared.request().owner())||!owner.peerId().equals(prepared.target().replica().peerId()))throw new IOException("Fresh cohort qualification changed original owner");var cap=owner.cohort();if(cap==null||!cap.nodeId().equals(prepared.target().replica().nodeId())||!cap.nodeIncarnation().equals(prepared.target().replica().nodeIncarnation())||prepared.request().ttl().toMillis()>cap.maximumReadonlyMillis()||prepared.request().ttl().toMillis()>cap.poolMaximumAgeMillis())throw new IOException("Fresh native cohort capabilities changed");var pool=new Pool(cap.nodeId(),cap.nodeIncarnation(),cap.processIncarnation(),cap.poolId());pools.computeIfAbsent(pool,k->new ArrayList<>()).add(new RatisDatabaseBackupJournal.Member(prepared.request().fence().fenceId(),group,prepared.request().snapshotId(),prepared.request().owner(),prepared.target().replica().replicaId(),prepared.request().ttl().toMillis(),hash(prepared.bytes())));targets.put(group,prepared.target());return null;}catch(IOException failed){throw new CompletionException(failed);}}));}
        return work.thenApply(ignored->{if(pools.size()>policy.maximumCohorts())throw new CompletionException(new IOException("Qualified cohort count exceeds policy"));var requests=new ArrayList<RatisDatabaseBackupJournal.CohortRequest>();for(var entry:pools.entrySet()){var pool=entry.getKey();var request=new RatisDatabaseBackupJournal.CohortRequest(UUID.randomUUID(),pool.incarnation,pool.process,pool.pool,entry.getValue());var captures=new HashMap<UUID,RatisSnapshotCaptureRequest>();for(var member:request.members())captures.put(member.groupId(),frozen.get(member.groupId()).request());request(new Request(request,captures));requests.add(request);}return List.copyOf(requests);});
    }
    @Override public CompletableFuture<Map<UUID,RatisSnapshotCaptureRequest.Result>> capture(RatisDatabaseBackupJournal.CohortRequest cohort,Map<UUID,RatisRoutedClient.PreparedSnapshotCapture> frozen)throws IOException{
        var captures=new HashMap<UUID,RatisSnapshotCaptureRequest>();for(var member:cohort.members()){var prepared=frozen.get(member.groupId());if(prepared==null)throw new IOException("Frozen cohort member absent");captures.put(member.groupId(),prepared.request());targets.put(member.groupId(),prepared.target());}
        return call(cohort,CAPTURE,request(new Request(cohort,captures))).thenApply(reply->{if(reply.phase()==Phase.PENDING||reply.phase()==Phase.DRAINING)throw new CompletionException(new IOException("Original cohort capture still "+reply.phase()));if(reply.phase()!=Phase.CAPTURED)throw new CompletionException(new RatisSnapshotLostException("Original cohort capture is "+reply.phase()));var expected=cohort.members().stream().map(RatisDatabaseBackupJournal.Member::groupId).collect(java.util.stream.Collectors.toSet());if(!reply.captures().keySet().equals(expected))throw new CompletionException(new IOException("Cohort result coverage changed"));for(var member:cohort.members()){var token=reply.captures().get(member.groupId()).token();if(!token.ownerIncarnation().equals(member.owner())||!token.snapshotId().equals(member.snapshotId()))throw new CompletionException(new IOException("Cohort result changed original pin"));}return reply.captures();});
    }
    private CompletableFuture<Reply> call(RatisDatabaseBackupJournal.CohortRequest request,int kind,byte[] body)throws IOException{var group=request.members().getFirst().groupId();var target=targets.get(group);if(target==null){var member=request.members().getFirst();var frozen=frozenCapture.apply(group);if(frozen==null||!Arrays.equals(hash(frozen.bytes()),member.preparedDigest())||!frozen.request().owner().equals(member.owner())||!frozen.target().replica().replicaId().equals(member.replica()))throw new IOException("Original cohort voter route not restored");target=frozen.target();targets.put(group,target);}return client(group).cohortQuery(target,kind,body).thenApply(bytes->{try{return reply(bytes,reference(request));}catch(IllegalArgumentException malformed){throw new CompletionException(new IOException("Invalid original cohort reply",malformed));}});}
    @Override public CompletableFuture<Void> requireLive(RatisDatabaseBackupJournal.CohortRequest request,Map<UUID,SnapshotFenceStatus.Capture> original)throws IOException{return call(request,STATE,reference(reference(request))).thenApply(reply->{if(reply.phase()!=Phase.CAPTURED)throw new CompletionException(new RatisSnapshotLostException("Original cohort no longer live"));for(var member:request.members())if(!Objects.equals(original.get(member.groupId()),reply.captures().get(member.groupId()).token()))throw new CompletionException(new RatisSnapshotLostException("Original cohort pin changed"));return null;});}
    @Override public CompletableFuture<Void> cancelAndDrain(RatisDatabaseBackupJournal.CohortRequest request)throws IOException{return call(request,CANCEL,reference(reference(request))).thenApply(reply->{if(reply.phase()!=Phase.RELEASED&&reply.phase()!=Phase.GONE)throw new CompletionException(new IOException("Actual cohort/native cleanup still active"));return null;});}
}
